### Step 7: Add tree structure verification test

In `tests/parse_rust_test.rs`, add a test that parses a multi-level nesting (module containing impl containing method) and verifies the tree shape:

```rust
#[test]
fn test_tree_structured_symbols() {
    let src = r#"
mod inner {
    struct Foo;
    impl Foo {
        fn bar(&self) {}
    }
}
"#;
    let result = parse_file(src, "rust", "test.rs").unwrap();
    assert_eq!(result.symbols.len(), 1); // only top-level mod
    let module = &result.symbols[0];
    assert_eq!(module.short_name, "inner");
    assert_eq!(module.children.len(), 2); // Foo struct + impl Foo
    let impl_sym = module.children.iter().find(|s| s.kind == SymbolKind::Impl).unwrap();
    assert_eq!(impl_sym.children.len(), 1);
    assert_eq!(impl_sym.children[0].short_name, "bar");

    // flatten preserves all symbols
    let flat = flatten_symbols(&result.symbols);
    assert_eq!(flat.len(), 4); // mod, struct, impl, method
}
```

